<?php
session_start(); require_once __DIR__ . '/../lead-engine/config.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sbq($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25]);$b=curl_exec($ch);curl_close($ch);$d=json_decode($b,true);return is_array($d)?$d:[];}
$rows=sbq('columbo_content_finds?select=*&order=repurpose_score.desc,created_at.desc&limit=150');
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/dashboard/assets/goliath-ui.css?v=36"><title>Columbo Content Vault</title></head><body><div class="g-shell"><?php require __DIR__.'/includes/goliath-sidebar-v34.php'; ?><main class="g-main"><section class="g-top"><div><h1>Columbo Content Vault</h1><p>High-value old content worth repurposing with better hooks and distribution.</p></div></section><section class="g-panel"><h2>Review Queue <span><?=count($rows)?></span></h2><div class="g-tableWrap"><table class="g-stealthTable"><thead><tr><th>Score</th><th>Content</th><th>Platform</th><th>Hook</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['repurpose_score']??0)?></td><td><div class='g-name'><?=h($r['title']??'Content Find')?></div><div class='g-subtle'><?=h($r['content_url']??'')?></div></td><td><?=h($r['platform']??'')?></td><td><?=h($r['recommended_hook']??'')?></td><td><?=h($r['recommended_format']??'Send to Scorsese')?></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>